starter.css:
.session-card {
  padding: 12px 16px;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  background: white;
}
.session-card:hover {
  translate: 0 -2px;
  box-shadow: 0 6px 16px rgb(15 23 42 / 0.12);
}
.status { margin: 0; color: #b91c1c; font-weight: 600; }
.live-dot {
  position: relative;
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: currentColor;
}
.live-dot::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: currentColor;
}

